import json,sys,base64,re
def dec(d):
    d=d.replace('-','+').replace('_','/')
    return base64.b64decode(d+'='*(-len(d)%4)).decode('utf-8','replace')
def walk(p):
    out=[]
    if p.get('body',{}).get('data') and p.get('mimeType','text/plain').startswith('text/plain'):
        out.append(dec(p['body']['data']))
    for c in p.get('parts',[]) or []:
        out+=walk(c)
    if not out and p.get('body',{}).get('data'):
        out.append(dec(p['body']['data']))
    return out
for f in sys.argv[1:]:
    t=json.loads(json.load(open(f))['result'])
    msgs=t.get('messages',[t])
    for m in msgs:
        h={x['name']:x['value'] for x in m['payload'].get('headers',[])}
        print('=====',h.get('Date'),'|',h.get('From'),'->',h.get('To'),'| cc',h.get('Cc'),'|',h.get('Subject'))
        body='\n'.join(walk(m['payload']))
        # strip quoted
        lines=[l for l in body.split('\n') if not l.startswith('>')]
        b='\n'.join(lines)
        b=re.split(r'\nOn .{5,80}wrote:',b)[0]
        print(b.strip()[:3000])
EOF
